// ==================== BYTECODE TỪ REMIX ====================
const CONTRACT_BYTECODE = "";

// ==================== DEPLOY FUNCTION ====================
async function deploy() {
    console.log('🚀 Bắt đầu deploy contract lên Ganache...\n');
    
    const web3 = new Web3(process.env.RPC_URL || 'http://127.0.0.1:7545');
    
    try {
        const accounts = await web3.eth.getAccounts();
        const deployer = accounts[0];
        
        console.log(`📡 Kết nối đến: ${process.env.RPC_URL || 'http://127.0.0.1:7545'}`);
        console.log(`👤 Deployer: ${deployer}`);
        
        const balance = await web3.eth.getBalance(deployer);
        console.log(`💰 Balance: ${web3.utils.fromWei(balance, 'ether')} ETH\n`);
        
        if (!CONTRACT_ABI.length) {
            console.error('❌ LỖI: ABI trống!');
            return;
        }
        
        if (CONTRACT_BYTECODE.length < 100) {
            console.error('❌ LỖI: Bytecode không hợp lệ!');
            return;
        }
        
        const contract = new web3.eth.Contract(CONTRACT_ABI);
        
        console.log('⏳ Đang deploy...');
        
        const deployTx = contract.deploy({
            data: CONTRACT_BYTECODE,
            arguments: []
        });
        
        const gas = await deployTx.estimateGas({ from: deployer });
        console.log(`   Gas ước tính: ${gas}`);
        
        const deployedContract = await deployTx.send({
            from: deployer,
            gas: gas + 200000,
            gasPrice: web3.utils.toWei('20', 'gwei')
        });
        
        const contractAddress = deployedContract.options.address;
        console.log('\n✅ DEPLOY THÀNH CÔNG!');
        console.log(`   📍 Contract Address: ${contractAddress}`);
        
        // Lưu contract address vào .env
        const envPath = path.join(__dirname, '.env');
        let envContent = '';
        if (fs.existsSync(envPath)) {
            envContent = fs.readFileSync(envPath, 'utf8');
        }
        
        if (envContent.includes('CONTRACT_ADDRESS=')) {
            envContent = envContent.replace(/CONTRACT_ADDRESS=.*/g, `CONTRACT_ADDRESS=${contractAddress}`);
        } else {
            envContent += `\nCONTRACT_ADDRESS=${contractAddress}\n`;
        }
        fs.writeFileSync(envPath, envContent);
        console.log(`   💾 Đã lưu contract address vào .env`);
        
        // Lưu ABI vào file
        fs.writeFileSync(path.join(__dirname, 'contractABI.json'), JSON.stringify(CONTRACT_ABI, null, 2));
        console.log(`   💾 Đã lưu ABI vào contractABI.json`);
        
        console.log('\n🎉 DEPLOY THÀNH CÔNG!');
        
    } catch (error) {
        console.error('\n❌ Deploy thất bại:', error.message);
        console.error('\n💡 Kiểm tra:');
        console.error('   1. Ganache đang chạy');
        console.error('   2. RPC đúng');
        console.error('   3. Bytecode và ABI chính xác');
    }
}

deploy();